'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');

function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}
function outcome(promise) {
  return promise.then(value => ({ value }), reason => ({ reason }));
}
const mutations = {
  invalidate: cache => cache.invalidate('key'),
  clear: cache => cache.clear(),
  set: cache => cache.set('key', 'set value')
};

for (const [mutation, mutate] of Object.entries(mutations)) {
  for (const oldFails of [false, true]) {
    for (const newFails of [false, true]) {
      for (const oldFirst of [false, true]) {
        test(`${mutation}: old ${oldFails ? 'rejects' : 'resolves'}, new ${newFails ? 'rejects' : 'resolves'}, ${oldFirst ? 'old' : 'new'} first`, async () => {
          let time = 0;
          const gates = [deferred(), deferred(), deferred()];
          let calls = 0;
          const cache = createCache({ now: () => time, ttlMs: 10, load: () => gates[calls++].promise });
          const old = outcome(cache.get('key'));
          const oldJoin = outcome(cache.get('key'));
          await Promise.resolve();
          assert.equal(calls, 1);
          assert.equal(mutate(cache), undefined);
          if (mutation === 'set') {
            assert.equal(await cache.get('key'), 'set value');
            time = 10;
            assert.equal(cache.size, 0);
          }
          const fresh = outcome(cache.get('key'));
          const freshJoin = outcome(cache.get('key'));
          await Promise.resolve();
          assert.equal(calls, 2);
          const oldReason = { old: true };
          const newReason = 'new failure';
          const settleOld = async () => {
            gates[0][oldFails ? 'reject' : 'resolve'](oldFails ? oldReason : 'old');
            const expected = oldFails ? { reason: oldReason } : { value: 'old' };
            assert.deepEqual(await old, expected);
            assert.deepEqual(await oldJoin, expected);
          };
          const settleNew = async () => {
            gates[1][newFails ? 'reject' : 'resolve'](newFails ? newReason : 'fresh');
            const expected = newFails ? { reason: newReason } : { value: 'fresh' };
            assert.deepEqual(await fresh, expected);
            assert.deepEqual(await freshJoin, expected);
          };
          if (oldFirst) {
            await settleOld();
            assert.equal(cache.size, 0);
            const laterJoin = outcome(cache.get('key'));
            await Promise.resolve();
            assert.equal(calls, 2, 'obsolete completion must not detach the newer flight');
            await settleNew();
            assert.deepEqual(await laterJoin, newFails ? { reason: newReason } : { value: 'fresh' });
          } else {
            await settleNew();
            await settleOld();
          }
          assert.equal(cache.size, newFails ? 0 : 1);
          if (newFails) {
            const retry = cache.get('key');
            await Promise.resolve();
            assert.equal(calls, 3);
            gates[2].resolve('retry');
            assert.equal(await retry, 'retry');
          } else {
            assert.equal(await cache.get('key'), 'fresh');
            assert.equal(calls, 2);
          }
        });
      }
    }
  }
}

for (const [mutation, mutate] of Object.entries(mutations)) {
  test(`${mutation} before scheduled load and synchronously inside load`, async () => {
    const gate = deferred();
    let calls = 0;
    const cache = createCache({ now: () => 0, load() {
      calls++;
      if (calls === 1) mutate(cache);
      return calls === 1 ? gate.promise : 'fresh';
    } });
    const old = cache.get('key');
    await Promise.resolve();
    assert.equal(calls, 1);
    assert.equal(await cache.get('key'), mutation === 'set' ? 'set value' : 'fresh');
    gate.resolve('old');
    assert.equal(await old, 'old');
    assert.equal(await cache.get('key'), mutation === 'set' ? 'set value' : 'fresh');

    let earlyCalls = 0;
    const early = createCache({ now: () => 0, load: () => ++earlyCalls });
    const before = early.get('key');
    mutate(early);
    const after = early.get('key');
    assert.equal(await before, 1);
    assert.equal(await after, mutation === 'set' ? 'set value' : 2);
    assert.equal(await early.get('key'), mutation === 'set' ? 'set value' : 2);
  });
}

test('repeated invalidate barriers preserve the newest unresolved flight', async () => {
  const gates = [deferred(), deferred(), deferred()];
  let calls = 0;
  const cache = createCache({ now: () => 0, load: () => gates[calls++].promise });
  const first = cache.get('key');
  cache.invalidate('key');
  const second = cache.get('key');
  cache.invalidate('key');
  const third = cache.get('key');
  await Promise.resolve();
  assert.equal(calls, 3);
  gates[1].resolve('second');
  assert.equal(await second, 'second');
  gates[0].resolve('first');
  assert.equal(await first, 'first');
  assert.equal(cache.size, 0);
  const join = cache.get('key');
  await Promise.resolve();
  assert.equal(calls, 3);
  gates[2].resolve('third');
  assert.equal(await third, 'third');
  assert.equal(await join, 'third');
  assert.equal(await cache.get('key'), 'third');
});

test('set retains its insertion TTL despite obsolete load completion', async () => {
  let time = 0;
  let calls = 0;
  const gate = deferred();
  const cache = createCache({ now: () => time, ttlMs: 10, load: () => ++calls === 1 ? gate.promise : 'fresh' });
  const old = cache.get('key');
  await Promise.resolve();
  time = 5;
  cache.set('key', 'set value');
  time = 14;
  gate.resolve('old');
  assert.equal(await old, 'old');
  assert.equal(await cache.get('key'), 'set value');
  time = 15;
  assert.equal(cache.size, 0);
  assert.equal(await cache.get('key'), 'fresh');
  assert.equal(calls, 2);
});

test('clear detaches all flights and removes all stored values', async () => {
  const gates = new Map([['a', deferred()], ['b', deferred()]]);
  const calls = new Map();
  const cache = createCache({ now: () => 0, load(key) {
    const count = (calls.get(key) || 0) + 1;
    calls.set(key, count);
    return count === 1 ? gates.get(key).promise : `fresh ${key}`;
  } });
  cache.set('stored', 'value');
  const a = cache.get('a');
  const b = outcome(cache.get('b'));
  await Promise.resolve();
  cache.clear();
  assert.equal(cache.size, 0);
  assert.equal(await cache.get('a'), 'fresh a');
  assert.equal(await cache.get('b'), 'fresh b');
  gates.get('a').resolve('old a');
  gates.get('b').reject(null);
  assert.equal(await a, 'old a');
  assert.deepEqual(await b, { reason: null });
  assert.equal(await cache.get('a'), 'fresh a');
  assert.equal(await cache.get('b'), 'fresh b');
  assert.equal(cache.size, 2);
});

for (const kind of ['throw', 'reject', 'thenable', 'getter']) {
  test(`${kind} rejection preserves reason, deduplicates, and allows retry`, async () => {
    const reason = kind === 'throw' ? undefined : { kind };
    let calls = 0;
    const cache = createCache({ now: () => 0, load() {
      if (++calls > 1) return 'retry';
      if (kind === 'throw') throw reason;
      if (kind === 'reject') return Promise.reject(reason);
      if (kind === 'thenable') return { then(resolve, reject) { reject(reason); } };
      return { get then() { throw reason; } };
    } });
    const first = outcome(cache.get('key'));
    const second = outcome(cache.get('key'));
    assert.deepEqual(await first, { reason });
    assert.deepEqual(await second, { reason });
    assert.equal(calls, 1);
    assert.equal(cache.size, 0);
    assert.equal(await cache.get('key'), 'retry');
    assert.equal(calls, 2);
  });
}

test('TTL starts at commit and expires at the exact deadline', async () => {
  let time = 0;
  let calls = 0;
  const gate = deferred();
  const cache = createCache({ now: () => time, ttlMs: 10, load: () => ++calls === 1 ? gate.promise : 'fresh' });
  const first = cache.get('key');
  assert.equal(cache.size, 0);
  time = 100;
  const join = cache.get('key');
  await Promise.resolve();
  assert.equal(calls, 1);
  gate.resolve(undefined);
  assert.equal(await first, undefined);
  assert.equal(await join, undefined);
  time = 109;
  assert.equal(cache.size, 1);
  assert.equal(await cache.get('key'), undefined);
  assert.equal(calls, 1);
  time = 110;
  assert.equal(cache.size, 0);
  assert.equal(await cache.get('key'), 'fresh');
});

test('zero TTL deduplicates unsettled loads but never settled values', async () => {
  const gates = [deferred(), deferred()];
  let calls = 0;
  const cache = createCache({ ttlMs: 0, now: () => 0, load: () => gates[calls++].promise });
  const first = cache.get('key');
  const join = cache.get('key');
  await Promise.resolve();
  assert.equal(calls, 1);
  gates[0].resolve(null);
  assert.equal(await first, null);
  assert.equal(await join, null);
  assert.equal(cache.size, 0);
  const second = cache.get('key');
  await Promise.resolve();
  assert.equal(calls, 2);
  gates[1].resolve('second');
  assert.equal(await second, 'second');
});

test('reentrant own-key reads join; other keys load independently', async () => {
  let ownJoin, other;
  const calls = [];
  const cache = createCache({ now: () => 0, load(key) {
    calls.push(key);
    assert.equal(arguments.length, 1);
    if (key === 'self') {
      ownJoin = cache.get('self');
      other = cache.get('other');
    }
    return { then(resolve) { resolve(key); } };
  } });
  assert.equal(await cache.get('self'), 'self');
  assert.equal(await ownJoin, 'self');
  assert.equal(await other, 'other');
  assert.deepEqual(calls, ['self', 'other']);
});

test('Map key identity, nullish values, and instance isolation', async () => {
  let calls = 0;
  const cache = createCache({ now: () => 0, load: () => ++calls });
  const a = {}, b = {};
  cache.set(NaN, undefined);
  cache.set(-0, null);
  cache.set(a, 'a');
  cache.set(b, 'b');
  assert.equal(await cache.get(NaN), undefined);
  assert.equal(await cache.get(+0), null);
  assert.equal(await cache.get(a), 'a');
  assert.equal(await cache.get(b), 'b');
  assert.equal(cache.size, 4);
  assert.equal(calls, 0);
  const other = createCache({ now: () => 0, load: () => 'other' });
  assert.equal(await other.get(a), 'other');
  cache.invalidate(a);
  assert.equal(await other.get(a), 'other');
});

